<script setup lang="ts">
import { onBeforeUnmount,onMounted,ref } from 'vue';import { useRouter } from 'vue-router';
import { request,errorText } from '../api';import { session } from '../session';import type { ConfigurationState } from '../types';
import ResourceWorkspace from './resource-workspace.vue';
const state=ref<ConfigurationState>({revision:'0',configuration:{nodes:[],tenants:[],networks:[]}});const busy=ref(false);const error=ref('');const router=useRouter();let active=new AbortController();
async function load(){active.abort();active=new AbortController();const signal=active.signal;busy.value=true;error.value='';try{state.value=await request<ConfigurationState>('/desired',{signal});}catch(e){if(!signal.aborted)error.value=errorText(e);}finally{if(!signal.aborted)busy.value=false;}}
onMounted(load);onBeforeUnmount(()=>active.abort());
</script>
<template><section class="sdn-page"><div class="page-head"><div><h1>租户与网络</h1><p class="subtitle">Controller 期望配置 · 版本 {{state.revision}}。实际生效情况请结合任务与观测判断。</p></div><div><el-button :loading="busy" @click="load">刷新配置</el-button><el-button v-if="session.role==='admin'" type="primary" @click="router.push('/changes')">编辑配置</el-button></div></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><ResourceWorkspace/><h2>全局声明式配置</h2><div class="summary-grid"><div class="metric"><div class="label">配置节点</div><div class="value">{{state.configuration.nodes.length}}</div></div><div class="metric"><div class="label">租户</div><div class="value">{{state.configuration.tenants.length}}</div></div><div class="metric"><div class="label">二层网络</div><div class="value">{{state.configuration.networks.length}}</div></div></div><div class="panel"><h2>租户 / L3VNI</h2><el-table :data="state.configuration.tenants" empty-text="尚未配置租户"><el-table-column prop="name" label="租户"/><el-table-column prop="id" label="ID"/><el-table-column prop="fabricId" label="Fabric"/><el-table-column prop="l3vni" label="L3VNI"/><el-table-column label="导入 RT"><template #default="{row}">{{row.importRts?.join(', ')}}</template></el-table-column><el-table-column label="部署数"><template #default="{row}">{{row.placements?.length||0}}</template></el-table-column></el-table></div><div class="panel"><h2>二层网络 / L2VNI</h2><el-table :data="state.configuration.networks" empty-text="尚未配置网络"><el-table-column type="expand"><template #default="{row}"><pre class="code">{{JSON.stringify(row.placements,null,2)}}</pre></template></el-table-column><el-table-column prop="id" label="网络 ID"/><el-table-column prop="tenantId" label="所属租户"/><el-table-column prop="l2vni" label="L2VNI"/><el-table-column label="导入 RT"><template #default="{row}">{{row.importRts?.join(', ')}}</template></el-table-column><el-table-column label="部署数"><template #default="{row}">{{row.placements?.length||0}}</template></el-table-column></el-table></div><div class="panel"><h2>节点配置</h2><el-table :data="state.configuration.nodes" empty-text="尚无节点目标配置"><el-table-column prop="name" label="名称"/><el-table-column prop="role" label="角色"/><el-table-column prop="routerId" label="Router ID"/><el-table-column prop="vtepIp" label="VTEP"/><el-table-column prop="asn" label="ASN"/></el-table></div><div class="panel"><h2>完整资源配置</h2><pre class="code">{{JSON.stringify(state.configuration,null,2)}}</pre></div></section></template>
